import demoCatalog from './demo-catalog.json';
import observedSnapshot from './observed-snapshot.json';
import { ALLOW_DEMO_FALLBACK, API_BASE_URL, HAS_CONFIGURED_API, PUBLIC_API_URL, SITE_NAME } from './config';
import type { AppConfig, Category, Product, ProductDetail, ProductQuery, ProductsResponse } from './types';
export { formatPrice, formatNumber, formatDate, pluralize } from './format';

/** The checked-in fixture is generated by backend/app/demo.py. It always remains explicitly synthetic. */
export const products = [...demoCatalog, ...(typeof process !== 'undefined' && process.env.EXPORT_STATIC === '1' ? observedSnapshot : [])] as unknown as ProductDetail[];
export const demoProducts = products;

export function getCategories(items: Product[] = products): Category[] {
  return (['ssd', 'ram', 'gpu'] as const).map(id => ({
    id,
    name: { ssd: 'SSD-накопители', ram: 'Оперативная память', gpu: 'Видеокарты' }[id],
    count: items.filter(product => product.category === id).length,
  }));
}

type ApiResult<T> = {kind:'ok';data:T}|{kind:'demo'|'not_found'|'error'};
async function apiFetch<T>(path: string): Promise<ApiResult<T>> {
  // A static export is deliberately self-contained and never claims its fixture is live data.
  if (import.meta.env.STATIC_DEMO === '1' || (typeof process !== 'undefined' && process.env.EXPORT_STATIC === '1')) return {kind:'demo'};
  let response: Response;
  try {
    const base = import.meta.env.SSR ? API_BASE_URL : PUBLIC_API_URL;
    response = await fetch(`${base}${path}`, { signal: AbortSignal.timeout(1500) });
  } catch { return {kind:ALLOW_DEMO_FALLBACK&&!HAS_CONFIGURED_API?'demo':'error'}; }
  if (response.status === 404) return {kind:'not_found'};
  if (!response.ok) return {kind:'error'};
  try {return {kind:'ok',data:await response.json() as T};}
  catch {return {kind:'error'};}
}

export function filterProducts(items: ProductDetail[], query: ProductQuery = {}): ProductDetail[] {
  const term = query.q?.toLocaleLowerCase('ru-RU').trim();
  const filtered = items.filter(product =>
    (!term || `${product.name} ${product.brand} ${product.model} ${product.mpn}`.toLocaleLowerCase('ru-RU').includes(term)) &&
    (!query.category || query.category === 'all' || product.category === query.category) &&
    (!query.brand || product.brand === query.brand) &&
    (query.min_price == null || (product.price != null && product.price >= query.min_price)) &&
    (query.max_price == null || (product.price != null && product.price <= query.max_price)) &&
    (!query.deals_only || product.status === 'good')
  );
  return filtered.sort((a, b) => {
    if (query.sort === 'price_asc') return (a.price ?? Infinity) - (b.price ?? Infinity);
    if (query.sort === 'price_desc') return (b.price ?? -Infinity) - (a.price ?? -Infinity);
    if (query.sort === 'rating') return (b.rating ?? -1) - (a.rating ?? -1);
    if (query.sort === 'popular') return b.reviews_count - a.reviews_count;
    return (b.discount_percent ?? -1) - (a.discount_percent ?? -1);
  });
}

export async function getProductsResult(query: ProductQuery = {}): Promise<{items:ProductDetail[];available:boolean}> {
  const response = await apiFetch<ProductsResponse>('/api/products?page_size=100');
  if (response.kind === 'ok' && Array.isArray(response.data?.items)) {
    // Fetch every API page before applying client-side search and filters; a
    // partial response would otherwise look like a complete catalogue.
    const {total, page_size: pageSize} = response.data;
    if (!Number.isSafeInteger(total) || total < 0 || !Number.isSafeInteger(pageSize) || pageSize < 1 || pageSize > 100) return {items:[],available:false};
    const collected = [...response.data.items];
    const pages = Math.ceil(total / pageSize);
    for (let page = 2; page <= pages; page++) {
      const next = await apiFetch<ProductsResponse>(`/api/products?page_size=100&page=${page}`);
      // Do not substitute demo data or silently display an incomplete list if
      // the API fails part way through paging.
      if (next.kind !== 'ok' || !Array.isArray(next.data?.items) || next.data.page !== page || next.data.page_size !== pageSize || next.data.total !== total) return {items:[],available:false};
      collected.push(...next.data.items);
    }
    if (collected.length < total) return {items:[],available:false};
    const items = collected.map(item => ({ ...item, offers: [], reviews: emptyReviews() })) as ProductDetail[];
    return {items:filterProducts(items, query),available:true};
  }
  return response.kind === 'demo' ? {items:filterProducts([...products], query),available:true} : {items:[],available:false};
}

export async function getProducts(query: ProductQuery = {}): Promise<ProductDetail[]> {
  return (await getProductsResult(query)).items;
}

export async function getProductResult(slug: string): Promise<{product:ProductDetail|null;available:boolean}> {
  const response = await apiFetch<ProductDetail>(`/api/products/${encodeURIComponent(slug)}`);
  if (response.kind === 'ok') {
    const product = response.data;
    return product?.slug === slug && Array.isArray(product.offers) ? {product,available:true} : {product:null,available:false};
  }
  if (response.kind === 'demo') return {product:products.find(item => item.slug === slug) ?? null,available:true};
  return {product:null,available:response.kind==='not_found'};
}

export async function getProduct(slug: string): Promise<ProductDetail | null> {
  return (await getProductResult(slug)).product;
}

export async function getAppConfig(): Promise<AppConfig> {
  const response = await apiFetch<AppConfig>('/api/config');
  return response.kind === 'ok' ? response.data : { brand: SITE_NAME, telegram_enabled: false, telegram_username: null, data_mode: response.kind === 'demo' ? 'demo' : 'unavailable' };
}

function emptyReviews(): ProductDetail['reviews'] {
  const empty = {count: 0, average: null, low_share: null, delta: null, warning: null, uncertainty: null, previous_count: 0, period_start: null, period_end: null};
  return { slices: {all: empty, '500': empty, '100': empty, '10': empty, '30d': empty, '90d': empty}, last_review_at: null, source: 'unavailable', coverage: 'Детальные отзывы недоступны', individual_available: false, availability: 'unavailable' };
}
